C=Path(__file__).resolve().parent;P=Path('/home/philip/binary-eagle-decoding');R=P/'runs/binary-methods-20261104-01';E=C.parents[1]/'experiments/binary-methods-20261104';E.mkdir(parents=True,exist_ok=True)
