html='''<!doctype html><html><head><meta charset="utf-8"><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground);margin:0}section{margin:14px 0 24px}h3{font-size:17px;margin:0 0 8px}p,summary{font-size:13px;color:var(--muted-foreground);line-height:1.5}select{background:var(--secondary);color:var(--foreground);border:1px solid var(--border);border-radius:6px;padding:7px;max-width:100%;margin:6px 0}svg{display:block;width:100%;height:375px;overflow:visible}text{fill:currentColor;font-family:var(--font-sans,system-ui);font-size:12px}.legend{display:flex;flex-wrap:wrap;gap:15px;font-size:12px}.swatch{display:inline-block;width:10px;height:10px;margin-right:5px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:right;padding:6px;border-bottom:1px solid var(--border)}td:first-child,th:first-child{text-align:left}button{font:inherit}details{margin:12px 0}.note{border-left:3px solid var(--chart-3);padding-left:10px}
</style></head><body>
<section><h3>Native binary projection pipeline · lower is better</h3><p>RTX 5080 · µs of CUDA kernel time per speculative round · 13 binary projections. One warmed code request; this is not full draft latency or GPU occupancy.</p><div class="legend"><span><i class="swatch" style="background:var(--chart-1)"></i>Activation quantization / packing</span><span><i class="swatch" style="background:var(--chart-2)"></i>Extra layout / representation work</span><span><i class="swatch" style="background:var(--chart-3)"></i>Dot product + output scaling</span></div><svg id="pipeline" role="img" aria-label="Native binary projection pipeline timings"></svg></section>
<section><h3>End-to-end generation · higher is better</h3><select id="throughputMetric"><option value="decode_tps">Decode tokens/s — excludes prompt processing</option><option value="request_tps">Request tokens/s — includes prompt processing</option></select><p>Qwen3-4B F16 target + DSpark, draft length 5. Two repetitions × three reused prompts, up to 128 output tokens. Thin lines show the two aggregate repetition rates, not confidence intervals.</p><svg id="throughput" role="img" aria-label="Native generation throughput comparison"></svg><p class="note">A1 uses the same A8-trained weights with one-bit activations. Its acceptance loss is not a trained W1A1 result. All target outputs match; draft counters match across methods within each precision.</p></section>
<section><h3>Isolated projection · quantization through output</h3><select id="shape"><option value="9728,2560,7">7 positions · gate/up: 9,728 × 2,560</option><option value="2560,9728,7">7 positions · down: 2,560 × 9,728</option><option value="9728,2560,1">1 position · gate/up: 9,728 × 2,560</option><option value="2560,9728,1">1 position · down: 2,560 × 9,728</option></select><p>Median µs, lower is better. Three CUDA-graph repeats of 32 operations with resident synthetic inputs. Hover a bar for separately measured preparation and dot times. Tensor kernels here specialize in 7 positions.</p><svg id="micro" role="img" aria-label="Isolated projection timings"></svg></section>
<details><summary>Published LUT-GEMM FP16 kernel and measurement limits</summary><p>The unmodified published computation also ran successfully. Best of six small launch configurations:</p><table><thead><tr><th>Projection</th><th>1 position</th><th>7 positions</th></tr></thead><tbody id="lut"></tbody></table><p>These timings start with FP16 activations/scales and include shared LUT construction, dot work and output clearing. They omit activation quantization and weight transposition. They use approximate FP16 accumulation and are not an apples-to-apples A8/A1 speedup. The “shared LUT” bars above use an exact adapted integer-sum method and include per-call weight transposition. No SM occupancy or bandwidth counters were available. Small throughput gaps are inconclusive with this short panel; modern Qwen3.5/NVFP4 targets and DFlash were not tested here.</p></details>
<script>
const D=DATA;const names={A8_tensor:'A8 · Tensor Core default',A8_dp4a:'A8 · DP4A',A8_planes1:'A8 · Bit-serial, separate',A8_planes7:'A8 · Bit-serial, shared',A8_lut4:'A8 · Global LUT4',A8_sharedlut:'A8 · Shared LUT (exact)',A1_xor:'A1 · XOR / popcount',A1_bmma:'A1 · Binary MMA → INT8',A1_tensor:'A1 · Tensor Core adapter',A1_sharedlut:'A1 · Shared LUT (exact)'};
function chart(id,rows,max,unit){const svg=document.getElementById(id);const W=700,H=rows.length*34+35,x0=205,width=405;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.style.height=H+'px';let s='';for(let i=0;i<=4;i++){let v=max*i/4,xx=x0+width*i/4;s+=`<line x1="${xx}" y1="8" x2="${xx}" y2="${H-24}" stroke="var(--border)"/><text x="${xx}" y="${H-6}" text-anchor="middle">${v.toFixed(0)}</text>`;}rows.forEach((r,i)=>{let y=i*34+13;s+=`<text x="0" y="${y+14}">${names[r.arm]||r.arm}</text>`;let pos=x0;r.values.forEach((v,j)=>{let w=width*v/max;s+=`<rect x="${pos}" y="${y}" width="${w}" height="22" rx="2" fill="var(--chart-${r.values.length>1?j+1:r.arm.startsWith('A1')?4:1})"><title>${r.tip||names[r.arm]+': '+r.values.reduce((a,b)=>a+b,0).toFixed(2)+' '+unit}</title></rect>`;pos+=w;});if(r.range){let a=x0+width*r.range[0]/max,b=x0+width*r.range[1]/max;s+=`<line x1="${a}" x2="${b}" y1="${y+11}" y2="${y+11}" stroke="var(--foreground)" stroke-width="2"/>`;}s+=`<text x="${Math.max(pos+8,615)}" y="${y+15}">${r.values.reduce((a,b)=>a+b,0).toFixed(1)}</text>`;});svg.innerHTML=s;}
const native=D.native.map(r=>({arm:r.arm,values:Object.values(r.binary_stages_us).map(v=>v/r.speculative.rounds)}));chart('pipeline',native,Math.max(...native.map(r=>r.values.reduce((a,b)=>a+b,0)))*1.07,'µs');
function throughput(){let metric=document.getElementById('throughputMetric').value;let rs=D.throughput.map(r=>({arm:r.arm,values:[r[metric]],range:metric==='decode_tps'?[Math.min(...r.decode_tps_per_repetition),Math.max(...r.decode_tps_per_repetition)]:null,tip:`${r[metric].toFixed(2)} tokens/s; acceptance ${(r.acceptance*100).toFixed(1)}%`}));chart('throughput',rs,Math.max(...rs.map(r=>r.values[0]))*1.08,'tokens/s');}
function micro(){let [m,k,n]=document.getElementById('shape').value.split(',').map(Number);let rs=D.kernels.filter(r=>r.m===m&&r.k===k&&r.n===n).map(r=>({arm:r.mode,values:[r.full_us],tip:`Full ${r.full_us.toFixed(2)} µs; preparation ${r.prep_us.toFixed(2)} µs; dot ${r.dot_us.toFixed(2)} µs. Separately timed phases need not add exactly.`}));chart('micro',rs,Math.max(...rs.map(r=>r.values[0]))*1.07,'µs');}
document.getElementById('throughputMetric').onchange=throughput;document.getElementById('shape').onchange=micro;throughput();micro();
let median=a=>[...a].sort((a,b)=>a-b)[1];document.getElementById('lut').innerHTML=[[9728,2560,'Gate/up'],[2560,9728,'Down']].map(([m,k,label])=>`<tr><td>${label}</td>${[1,7].map(n=>`<td>${Math.min(...D.lutgemm.rows.filter(r=>r.m===m&&r.k===k&&r.n===n).map(r=>median(r.us))).toFixed(2)} µs</td>`).join('')}</tr>`).join('');
</script></body></html>'''.replace('DATA',json.dumps(x))
(E/'comparison.html').write_text(html);print(E/'comparison.html')
